#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using System;
using System.IO;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class EquipmentHealthMergeReceiptTests {
  const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/RunEquipmentMergeSource-20261005/";
  static JObject Sample()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/equipment-health-merge-sql-sample-20261005.json"));
  static JObject Pins()=>JObject.Parse(File.ReadAllText(Qa+"original-pins.json"));
  static string Digest(JToken value)=>BDirectAttackInput.Digest(value).Substring(7);
  static RunEquipmentStatSource Source(JObject snapshot=null){var pins=Pins();var p=snapshot??(JObject)Sample()["currentStatSnapshot"];return RunEquipmentStatSource.Read(p,p,snapshot==null?(string)pins["currentStatHash"]:(string)p["packetHash"],"a",snapshot==null?(string)pins["runId"]:(string)p["runId"],snapshot==null?(string)pins["originalContextHash"]:(string)p["originalContextHash"],(long)p["inventoryRevision"]);}
  static EquipmentHealthMergeReceipt Read(JObject receipt=null,JObject command=null,RunEquipmentStatSource source=null){var sample=Sample();var pins=Pins();receipt=receipt??(JObject)sample["committedReceipt"];command=command??(JObject)sample["command"];return EquipmentHealthMergeReceipt.Read(receipt,receipt,Digest(receipt),command,Digest(command),source??Source(),(string)pins["accountId"],(string)pins["runId"]);}
  [Test] public void CommittedMergeReceiptNeedsSeparateBoundaryFromStatProposal(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.EquipmentHealthMergeReceipt"));}
  [Test] public void OriginalCommittedReceiptMatchesIndependentCanonicalPinsAndContext(){var sample=Sample();var pins=Pins();var r=EquipmentHealthMergeReceipt.Read((JObject)sample["committedReceipt"],(JObject)sample["committedReceipt"],(string)pins["responseHash"],(JObject)sample["command"],(string)pins["requestHash"],Source(),"a",(string)pins["runId"]);Assert.AreEqual((string)pins["responseHash"],r.Hash);Assert.IsTrue(JToken.DeepEquals(sample["committedReceipt"],r.Capture()));Assert.AreEqual(917,(int)r.HealthCheckpoint("op_kyle")["hp"]);Assert.AreEqual(1834,(int)r.HealthCheckpoint("op_kyle")["maxHp"]);Assert.AreEqual(3,(int)r.Capture()["merge"]["instanceRevision"]);Assert.AreEqual(2,(int)r.Capture()["merge"]["effectRevision"]);Assert.AreEqual(3,(int)r.Capture()["merge"]["inventoryRevision"]);Assert.IsFalse(r.IsActualHeal);Assert.IsFalse(r.HasNativeAttackDefenseJournal);}
  [Test] public void PreparedCandidateAndProposedStatsCannotMasqueradeAsCommittedReceipt(){var sample=Sample();Assert.IsFalse((bool)sample["preparedCandidate"]["committed"]);Assert.Throws<ArgumentException>(()=>Read((JObject)sample["preparedCandidate"]));Assert.Throws<ArgumentException>(()=>Read((JObject)sample["currentStatSnapshot"]));Assert.IsFalse(Source().CanApplyToNative);Assert.Throws<InvalidOperationException>(()=>Source().RequireCommittedRuntimeSource());}
  [Test] public void CallerMutationsAndRepeatedOriginalRestoreCannotChangeReceipt(){var p=(JObject)Sample()["committedReceipt"];var s=Read(p);var original=s.Capture();p["health"][0]["after"]["hp"]=1;s.HealthCheckpoint("op_kyle")["hp"]=2;s.Capture()["merge"]["star"]=3;Assert.IsTrue(JToken.DeepEquals(original,s.Capture()));var replay=Read();Assert.AreEqual(s.Hash,replay.Hash);Assert.IsTrue(JToken.DeepEquals(original,replay.Capture()));Assert.IsTrue((bool)Sample()["sameKeyReplayVerified"]);}
  [TestCase("account")][TestCase("run")][TestCase("responsePin")][TestCase("requestPin")]
  public void IndependentAuthorityPinsCannotBeReplaced(string fault){var sample=Sample();var pins=Pins();Assert.Throws<ArgumentException>(()=>EquipmentHealthMergeReceipt.Read((JObject)sample["committedReceipt"],(JObject)sample["committedReceipt"],fault=="responsePin"?new string('0',64):(string)pins["responseHash"],(JObject)sample["command"],fault=="requestPin"?new string('0',64):(string)pins["requestHash"],Source(),fault=="account"?"foreign":"a",fault=="run"?"foreign-run":(string)pins["runId"]));}
  [TestCase("hp")][TestCase("target")][TestCase("instanceRevision")][TestCase("effectRevision")][TestCase("inventoryRevision")][TestCase("primary")][TestCase("consumed")][TestCase("star")]
  public void RehashedMutationCannotReplaceOriginalCommittedReceipt(string fault){var original=(JObject)Sample()["committedReceipt"];var p=(JObject)original.DeepClone();if(fault=="hp")p["health"][0]["after"]["hp"]=918;if(fault=="target")p["targets"][0]["targetId"]="op_sable";if(fault=="instanceRevision"||fault=="effectRevision"||fault=="inventoryRevision")p["merge"][fault]=4;if(fault=="primary")p["merge"]["resultInstanceId"]="foreign";if(fault=="consumed")p["merge"]["consumedInstanceId"]="foreign";if(fault=="star")p["merge"]["star"]=3;var sample=Sample();var pins=Pins();Assert.Throws<ArgumentException>(()=>EquipmentHealthMergeReceipt.Read(p,original,Digest(p),(JObject)sample["command"],(string)pins["requestHash"],Source(),"a",(string)pins["runId"]));}
  [TestCase("star3")][TestCase("heal")][TestCase("revision")][TestCase("effectRevision")][TestCase("supplies")][TestCase("anchor")][TestCase("dead")][TestCase("target")][TestCase("location")][TestCase("unknown")][TestCase("version")][TestCase("empty")]
  public void DiagnosticMalformedReceiptCannotWidenCommittedScope(string fault){var p=(JObject)Sample()["committedReceipt"];if(fault=="star3")p["merge"]["star"]=3;if(fault=="heal"){p["health"][0]["change"]=new JObject{["kind"]="ACTUAL_HP",["reason"]="HEAL",["hp"]=917};}if(fault=="revision")p["health"][0]["revision"]=4;if(fault=="effectRevision")p["merge"]["effectRevision"]=3;if(fault=="supplies")p["merge"]["suppliesCost"]=1;if(fault=="anchor")p["health"][0]["after"]["anchorHp"]=800;if(fault=="dead"){p["health"][0]["before"]["hp"]=0;p["health"][0]["before"]["anchorHp"]=0;}if(fault=="target")p["targets"][0]["targetId"]="op_sable";if(fault=="location")p["merge"]["resultLocation"]["slotIndex"]=1;if(fault=="unknown")p["extra"]=1;if(fault=="version")p["version"]="old";if(fault=="empty")p["health"]=new JArray();Assert.Throws<ArgumentException>(()=>Read(p));}
  [TestCase("commandId")][TestCase("expectedHealthRevision")][TestCase("expectedSecondaryEffectRevision")][TestCase("confirmation")]
  public void ChangedRequestCannotRestoreOldHealthEventEvenWithRecomputedRequestHash(string fault){var command=(JObject)Sample()["command"];if(fault=="commandId")command["merge"]["commandId"]="changed";if(fault=="expectedHealthRevision")command[fault]=1;if(fault=="expectedSecondaryEffectRevision")command["merge"][fault]=2;if(fault=="confirmation")command["merge"]["confirmedLosses"]=false;Assert.Throws<ArgumentException>(()=>Read(null,command));}
  [Test] public void OlderInventorySourceAndForeignRunEventCannotAuthorizeReceipt(){var p=(JObject)Sample()["currentStatSnapshot"];p["inventoryRevision"]=2;p.Remove("packetHash");p["packetHash"]=Digest(p);Assert.Throws<ArgumentException>(()=>Read(null,null,Source(p)));p=(JObject)Sample()["currentStatSnapshot"];p["runId"]="diagnostic-foreign-run";p["originalContext"]["runId"]="diagnostic-foreign-run";p["originalContextHash"]=Digest(p["originalContext"]);p.Remove("packetHash");p["packetHash"]=Digest(p);var foreign=Source(p);var sample=Sample();var pins=Pins();Assert.Throws<ArgumentException>(()=>EquipmentHealthMergeReceipt.Read((JObject)sample["committedReceipt"],(JObject)sample["committedReceipt"],(string)pins["responseHash"],(JObject)sample["command"],(string)pins["requestHash"],foreign,"a",foreign.RunId));}
  [Test] public void ExistingHpOwnerMatchesRebaseWithoutHealDriftOrRevival(){var r=Read();var v=new CombatVitals(1400,0,true);v.Damage(700,0,false);v.RebaseMaxHp(1624);Assert.AreEqual(812,v.Hp);v.RebaseMaxHp((int)r.HealthCheckpoint("op_kyle")["maxHp"]);Assert.AreEqual(917,v.Hp);v.RebaseMaxHp(1834);Assert.AreEqual(917,v.Hp);v.RebaseMaxHp(1400);Assert.AreEqual(700,v.Hp);var down=new CombatVitals(1600,0,true);down.Damage(1600,0,false);down.RebaseMaxHp(1834);Assert.AreEqual(0,down.Hp);File.WriteAllText(Qa+"hp-owner-reference.json",new JObject{["receiptHash"]=r.Hash,["reference"]="existing CombatVitals LOCAL oracle; no server receipt applied to live native",["beforeHp"]=812,["afterHp"]=917,["newMaxHp"]=1834,["duplicateRebaseHp"]=917,["revertedHp"]=v.Hp,["downAfterRebase"]=down.Hp,["isActualHeal"]=r.IsActualHeal}.ToString());}
  [Test] public void CommittedHpReceiptSuppliesNoNativeAttackDefenseJournal(){var r=Read();var f=BNamedOperatorSourceTests.Native();var n=f.adapter.CreateRuntime(f.binding,BOrdinaryGeometryTests.Geometry(f.binding),10000);var before=n.Capture();Assert.Throws<InvalidOperationException>(()=>r.RequireNativeAttackDefenseJournal());Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));Assert.AreEqual(1400,n.Hp("op_kyle"));Assert.IsFalse(r.HasNativeAttackDefenseJournal);Assert.Throws<ArgumentException>(()=>r.HealthCheckpoint("op_sable"));}
 }
}
#endif
